import { test, expect } from "@playwright/test";
import { SignInPage } from "../pages/sign-in.page";

test.describe("Customer account", () => {

  // @story:TOOL-13
  // @ac:1
  // @design:D1
  // @type:functional
  // @technique:state-transition
