      // @bdd2pw lane=rule rule=rule-50
      await expect(signInPage.page.getByText("My Account").first()).toBeVisible();
    });
  });

  // @story:TOOL-13
  // @ac:2
  // @design:D2
  // @type:functional
  // @technique:equivalence-partitioning
